import{Ct as e,Lt as t,St as n,Vt as r,Xt as i,_t as a,bt as o,n as s,xt as c}from"./chunks/framework.CpAKRyMe.js";var l=JSON.parse(`{"title":"从像素到关节（前置）：机械臂构型与三只眼睛","description":"一套双臂巡检机器人的物理形态：两条五轴臂挂在同一个腰部、升降柱与夹爪各一个，一台顶部相机加两台腕部相机加两台手部相机各自装在哪、看什么，以及这些构型如何决定了后面五篇的算法取舍","frontmatter":{"title":"从像素到关节（前置）：机械臂构型与三只眼睛","category":["机器人","硬件结构"],"tag":["机械臂","相机布置","自由度","坐标约定"],"description":"一套双臂巡检机器人的物理形态：两条五轴臂挂在同一个腰部、升降柱与夹爪各一个，一台顶部相机加两台腕部相机加两台手部相机各自装在哪、看什么，以及这些构型如何决定了后面五篇的算法取舍","date":"2026-11-22T17:45:00.000Z","updated":"2026-11-22T17:45:00.000Z","cover":"lucide:bot","ai":true,"breadcrumbs":[{"title":"首页","link":"/"},{"title":"机器人","link":"/articles/robotics"},{"title":"从像素到关节（前置）：机械臂构型与三只眼睛","link":""}]},"headers":[],"relativePath":"articles/robotics/manipulation/physical-setup.md","filePath":"articles/robotics/manipulation/physical-setup.md"}`),u={name:`articles/robotics/manipulation/physical-setup.md`};function d(s,l,u,d,f,p){let m=r(`VPNolebaseInlineLinkPreview`);return t(),o(`div`,null,[l[12]||=a(`blockquote`,null,[a(`p`,null,[a(`strong`,null,`关于本文的脱敏处理`),n(`：模块名、设备型号、配置项名称已做中性化替换，结构与规格保持原样。`)])],-1),l[13]||=a(`hr`,null,null,-1),l[14]||=a(`h2`,{id:`系列导航`,tabindex:`-1`},[n(`系列导航 `),a(`a`,{class:`header-anchor`,href:`#系列导航`,"aria-label":`Permalink to “系列导航”`},`​`)],-1),a(`ul`,null,[l[5]||=a(`li`,null,[a(`strong`,null,`前置：机械臂构型与三只眼睛`),n(` ← 当前`)],-1),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/coordinate-chain.html`},{default:i(()=>[...l[0]||=[n(`（一）坐标映射链与深度采样`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/hand-eye-calibration.html`},{default:i(()=>[...l[1]||=[n(`（二）手眼标定：从 ChArUco 到最小二乘`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/vision-detection.html`},{default:i(()=>[...l[2]||=[n(`（三）目标检测的工程化`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/inspection-orchestration.html`},{default:i(()=>[...l[3]||=[n(`（四）任务编排与安全判据`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/udp-control-loop.html`},{default:i(()=>[...l[4]||=[n(`（五）控制回路的时序与协议`,-1)]]),_:1})])]),l[15]||=c(`<hr><h2 id="为什么值得先看身体" tabindex="-1">为什么值得先看身体 <a class="header-anchor" href="#为什么值得先看身体" aria-label="Permalink to “为什么值得先看身体”">​</a></h2><p>后面五篇讲的全是算法：反投影、PnP、最小二乘、贪心匹配、力矩判据。但它们几乎每一处取舍，都是被这台机器的形态逼出来的。</p><p>挑三个例子说。末端姿态在代码里是个常数、从来不动，因为五轴臂加升降柱凑不出任意的六维位姿，而抓取工具又有固定朝向。顶部相机的外参只标一次就够、腕部相机不参与定位，背后是两种完全不同的视线关系：前者固定在机身上，后者跟着末端走。两条臂非得一条做完再做一条，是因为它们共用同一台相机和同一条控制通道，物理上没有并行空间。</p><p>先看清身体，后面每一个“为什么这么设计”才有落点。</p><hr><h2 id="一、身体-两条五轴臂挂在一个会转的腰上" tabindex="-1">一、身体：两条五轴臂挂在一个会转的腰上 <a class="header-anchor" href="#一、身体-两条五轴臂挂在一个会转的腰上" aria-label="Permalink to “一、身体：两条五轴臂挂在一个会转的腰上”">​</a></h2><p>从下往上拆：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>底盘（另有独立系统，本子系统只通过控制包里的三个速度字段与之交互）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ 腰部旋转（1 个自由度，度，正负 180° 可控）</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ├─ 左臂链：升降柱 + 5 个关节 + 夹爪</span></span>
<span class="line"><span>       └─ 右臂链：升降柱 + 5 个关节 + 夹爪</span></span></code></pre></div><p>两条臂挂在同一个腰部上，所以控制包里只有一个腰部角度字段，转腰时两条臂一起转。这一点在标定上很要紧，第六节会讲。</p><p>每侧臂链的驱动清单：</p><table tabindex="0"><thead><tr><th>部件</th><th>数量</th><th>自由度</th><th>单位</th><th>说明</th></tr></thead><tbody><tr><td>升降柱</td><td>1</td><td>1</td><td>米</td><td>线性执行器，串在臂链最前面</td></tr><tr><td>手臂关节</td><td>5</td><td>5</td><td>弧度</td><td>无刷伺服电机</td></tr><tr><td>夹爪</td><td>1</td><td>1</td><td>0 到 1 归一化</td><td>最大行程 90 mm</td></tr></tbody></table><p>单侧 7 个电机，左右合计 14 个，编号是连续的：电机 0 到 6 是左升降加左臂（升降、五个关节、夹爪），7 到 13 是右侧同样一套。这个编号顺序在标定教程和底层调试里都用得上，因为它解释了“为什么左侧的力矩数组下标从 0 起、关节从下标 1 起”。</p><p>电机的规格决定了后面碰撞判据的量级：24 V 无刷伺服，额定扭矩 3 N·m，峰值 7 N·m，减速比 10 比 1，CAN 总线 1 Mbps。也就是说，机械臂能拧出的力量在个位数牛顿米这个档，而第五节里那个 0.3 N·m 的碰撞阈值，是额定值的十分之一。</p><p>夹爪的 90 mm 行程是物理上限，决定了这套设备能夹多大的东西；抓取宽度在代码里用 0 到 1 归一化表达，换算关系由控制盒维护。</p><hr><h2 id="二、控制盒眼里的手臂-七个数字" tabindex="-1">二、控制盒眼里的手臂：七个数字 <a class="header-anchor" href="#二、控制盒眼里的手臂-七个数字" aria-label="Permalink to “二、控制盒眼里的手臂：七个数字”">​</a></h2><p>一条臂链在协议里展开成 7 个浮点，含义是固定的：</p><table tabindex="0"><thead><tr><th>下标</th><th>含义</th><th>单位</th></tr></thead><tbody><tr><td>0</td><td>升降柱位置</td><td>米</td></tr><tr><td>1 到 5</td><td>五个关节的角度</td><td>弧度</td></tr><tr><td>6</td><td>保留，本子系统不控制</td><td>弧度</td></tr></tbody></table><p>但本子系统<strong>不走关节角通道</strong>。控制包里同时有两个位置通道：关节角期望与末端笛卡尔位姿。巡检全程只填后者，也就是末端的三维坐标（米）加三个姿态角（度），前者的 7 个槽位全部填 0。逆解由控制盒内部完成。</p><p>这个选择有代价也有好处。代价是逆解的可行性不由我们控制，末端到不了的地方就是到不了，代码里只能用位移上限来拒绝明显越界的指令。好处是上层不需要懂运动学，点一个像素，算出一个末端坐标，剩下的交给下层。整篇文章里的“关节运动”其实都是末端在动，关节只是被逆解带出来的结果。</p><hr><h2 id="三、末端姿态为什么锁死" tabindex="-1">三、末端姿态为什么锁死 <a class="header-anchor" href="#三、末端姿态为什么锁死" aria-label="Permalink to “三、末端姿态为什么锁死”">​</a></h2><p>五轴加一根升降柱，听起来自由度不少。但升降柱只改变高度、不改变朝向，真正决定末端姿态的只有靠后的那几个关节。结果是：末端在位置上的可达范围很大，在姿态上的可达范围很窄。</p><p>而这套设备的末端装的不是夹爪本身，是一根有固定朝向的工具（探头或天线）。工具要对准目标，姿态就不能乱摆。</p><p>两个因素叠加，工程上的结论很直接：把姿态锁在标定姿态，只让位置三个自由度活动。</p><div class="language-python" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> build_target_pose</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(system_info, target_xyz, args):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pose </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pose_from_system_info(system_info)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pose.right_translation </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> target_xyz.copy()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pose.right_orientation_deg </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        args.right_roll_abs,          </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 标定姿态，来自配置常量</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        args.right_pitch_abs,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        args.right_yaw_abs,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pose</span></span></code></pre></div><p>姿态三个角在配置里是常量（往右偏零点几度、俯一点、偏一点），任何一次点击移动都不会改它。只有两种例外：Z 轴触到行程上限时把俯仰角再压 10 度（第四篇第七节），以及人工点动时的手动调整。</p><p>这个约束会传导到标定：外参是在某个姿态下求出来的，它就只在这个姿态附近可信。所以标定必须在工作姿态下做，不能拿一个姿态标定、换一个姿态工作。第二篇里那句“多姿态、多高度采样能更好地约束旋转误差”，说的也是同一个物理事实。</p><hr><h2 id="四、三只眼和两只手眼" tabindex="-1">四、三只眼和两只手眼 <a class="header-anchor" href="#四、三只眼和两只手眼" aria-label="Permalink to “四、三只眼和两只手眼”">​</a></h2><p>整套系统里最容易被算法文章忽略、又最影响结果的部分，是谁在看、从哪儿看。</p><table tabindex="0"><thead><tr><th>相机</th><th>数量</th><th>装在哪</th><th>看到什么</th><th>分辨率</th><th>在本子系统里的角色</th></tr></thead><tbody><tr><td>顶部深度相机</td><td>1</td><td>头部 / 机身顶部</td><td>俯视前方工作台面</td><td>1280×720@30</td><td>定位主源、巡检拍照、标定取图</td></tr><tr><td>腕部深度相机</td><td>2</td><td>左腕、右腕</td><td>跟随末端视角</td><td>1280×720</td><td>近距观察，不作定位主源</td></tr><tr><td>手部 USB 相机</td><td>2</td><td>夹爪 / 手部附近</td><td>极近距离，几乎贴着目标</td><td>640×480</td><td>读指示灯亮灭</td></tr></tbody></table><p>三台深度相机都同时输出彩色图和深度图，深度已经对齐到彩色光学系，所以反投影那三行公式可以直接用；这一点在第一篇里是个隐含前提。两台手部相机是普通 USB 摄像头，只出彩色，走的也不是同一个软件路径。</p><h3 id="_4-1-顶部相机-眼在手外" tabindex="-1">4.1 顶部相机：眼在手外 <a class="header-anchor" href="#_4-1-顶部相机-眼在手外" aria-label="Permalink to “4.1 顶部相机：眼在手外”">​</a></h3><p>顶部相机固定在头部，末端怎么动它都不动。这在手眼标定里叫“眼在手外”，它带来一个很大的好处：相机与机械臂的相对位姿是一个常量，外参标一次就能一直用。</p><p>坏处是视线被遮挡时不方便绕开，只能靠移动机械臂本身。不过巡检的场景里，目标就摆在工作台上，从上方俯视基本能看到全部，遮挡不是主要矛盾。</p><p>还有一点：视野覆盖整个工作台面，意味着一张照片里就能拿到这一轮所有的待检点，双边分组、扫描排序这些编排手段才有可能（第四篇）。</p><h3 id="_4-2-腕部相机-眼在手上" tabindex="-1">4.2 腕部相机：眼在手上 <a class="header-anchor" href="#_4-2-腕部相机-眼在手上" aria-label="Permalink to “4.2 腕部相机：眼在手上”">​</a></h3><p>两台腕部相机跟着末端走，视线关系每一帧都在变。要用它做定位，就得标定“末端姿态到相机位姿”的完整链条，等于给每个姿态都准备一套外参。</p><p>代价太大，收益有限，所以这套系统里它们是观察用的，不参与点击移动的坐标换算。这是一个典型的工程取舍：同一个传感器，用途不同，标定成本差一个数量级。</p><h3 id="_4-3-手部相机-最近的那只眼" tabindex="-1">4.3 手部相机：最近的那只眼 <a class="header-anchor" href="#_4-3-手部相机-最近的那只眼" aria-label="Permalink to “4.3 手部相机：最近的那只眼”">​</a></h3><p>夹爪旁边装的两只 USB 相机，距离目标最近，几乎是贴着看的。它们的活很单一：判断目标上的指示灯是亮着还是灭着。640×480 的分辨率、固定的距离、稳定的人工光源，够用了。</p><p>麻烦出在硬件上：这两台相机 vid/pid 完全相同，系统不靠设备 ID 区分，只能靠物理插口路径认左右；而且它们共享一个 USB HUB，不能同时保持长连接。第四篇里那套“互斥单帧池加子进程硬超时”的设计，就是为了绕开这两个限制。</p><hr><h2 id="五、把算法里的数字翻译成物理" tabindex="-1">五、把算法里的数字翻译成物理 <a class="header-anchor" href="#五、把算法里的数字翻译成物理" aria-label="Permalink to “五、把算法里的数字翻译成物理”">​</a></h2><p>算法文章里全是数值，脱开物理容易记混。这张对照表把常用的几个量还原回现场：</p><table tabindex="0"><thead><tr><th>代码里的量</th><th>物理含义</th></tr></thead><tbody><tr><td>末端中立位 (0.51, -0.20, 0.225) m</td><td>待机时末端停在离基准半米出头、高 22.5 cm 处；每次巡检从这儿出发、回这儿停</td></tr><tr><td>深度 1 m 上下最稳、2 m 以外误差涨到厘米级</td><td>结构光相机的通行表现，决定了点击移动的有效距离</td></tr><tr><td>13×7 方格、39 mm 边长</td><td>标定板实际尺寸约 507×273 mm，普通 A4 放不下，只能用大屏或大幅面打印</td></tr><tr><td>1.0 m 单次位移上限</td><td>超过这个量已经不是“够一下”，而是“重新部署”，程序会直接拒绝</td></tr><tr><td>3 mm 步长、80 ms 间隔</td><td>约 37.5 mm/s，比人手慢一个量级，作用是留出力矩突变被采到的窗口</td></tr><tr><td>0.3 N·m 力矩阈值</td><td>额定扭矩的十分之一；取值保守，是为了压掉误报</td></tr><tr><td>5 mm 的 Z 轴缺口</td><td>升降柱到顶后，指令与反馈之差就是被行程吃掉的量</td></tr><tr><td>90 mm 夹爪行程</td><td>能夹的最大宽度</td></tr><tr><td>腰部正负 180°</td><td>转腰改变相机与工作台的相对位姿，所以标定和巡检期间腰部必须保持不动</td></tr></tbody></table><p>最后一行的前提要单独说一句。腰部是两条臂和顶部相机共同的父节点，一转腰，相机相对工作台的位姿就变了，而外参描述的是“相机相对机械臂”，不是“相对世界”。所以这套外参的隐含前提是腰部不动。如果哪天要“转个身再抓”，那就得重标，或者为每个腰部角度维护一套表。</p><hr><h2 id="六、三个坐标系-三个前提" tabindex="-1">六、三个坐标系，三个前提 <a class="header-anchor" href="#六、三个坐标系-三个前提" aria-label="Permalink to “六、三个坐标系，三个前提”">​</a></h2><p>物理上只有三样东西：一台相机、一条臂、一块工作台。算法上要三层坐标：</p><table tabindex="0"><thead><tr><th>坐标系</th><th>轴向约定</th><th>单位</th><th>谁定义的</th></tr></thead><tbody><tr><td>像素系</td><td>u 向右、v 向下，原点在左上角</td><td>像素</td><td>相机驱动</td></tr><tr><td>相机光学系</td><td>Z 沿光轴指向景物，X 向右，Y 向下</td><td>米</td><td>相机内参</td></tr><tr><td>末端笛卡尔系</td><td>控制盒规定的三维坐标与姿态角</td><td>米 / 度</td><td>控制盒固件</td></tr></tbody></table><p>三者之间是一条单向的链：像素加深度反投影出相机系的三维点，再用一个 4×4（或 3×4）矩阵换到末端系。矩阵是从标定里来的，标定又依赖下面三个前提：</p><ol><li>腰部不动。动了，相机相对机械臂的位姿就变，矩阵失效。</li><li>末端姿态锁在标定姿态。姿态一变，腕部连杆的几何关系就变，同一个矩阵算出来的点会偏。</li><li>相机没有被碰过。顶部相机一旦被撞歪，标定当场作废，而且症状和“标定不准”一模一样，很难区分。</li></ol><p>这三点写在这里，是因为后面排障时它们最容易被漏掉：人总是先怀疑矩阵，再怀疑深度，最后才想到“相机是不是被碰了”“腰是不是转过”。</p><hr><h2 id="七、这套构型如何决定了后面的算法" tabindex="-1">七、这套构型如何决定了后面的算法 <a class="header-anchor" href="#七、这套构型如何决定了后面的算法" aria-label="Permalink to “七、这套构型如何决定了后面的算法”">​</a></h2><p>把物理约束列成账，五篇算法文章的主线就出来了：</p><table tabindex="0"><thead><tr><th>物理事实</th><th>算法后果</th><th>在哪一篇</th></tr></thead><tbody><tr><td>顶部相机固定、末端姿态锁死</td><td>点一次、算一次、动一次就够，不需要视觉伺服闭环</td><td>一、五</td></tr><tr><td>但一次映射的误差是开环的，不会自我纠正</td><td>精度几乎全押在标定上，于是有了整篇的标定文章</td><td>二</td></tr><tr><td>深度图有空洞、飞点和边沿混合</td><td>单点取深度不可靠，改成邻域中值加分位数判据</td><td>一</td></tr><tr><td>五轴加升降、姿态不可任意</td><td>不能斜着直接插过去，改成先横移对齐、再沿进给轴推进</td><td>五</td></tr><tr><td>两条臂共用一台相机和一条控制通道</td><td>物理上没有并行空间，必须串行，且每次切臂都要回待机位</td><td>四</td></tr><tr><td>手部相机共 HUB、同 vid/pid</td><td>只能互斥单帧，还要防阻塞读把进程卡死</td><td>四</td></tr><tr><td>电机额定扭矩只有个位数牛顿米</td><td>碰撞判据要在小信号上做，差分加位置误差双判据</td><td>四</td></tr></tbody></table><p>最后一行和第三行看似矛盾：一个是精度全押在标定上，一个是深度不可靠所以要稳一点取。其实不矛盾：标定决定系统偏多少，深度决定这一次点得准不准，两者误差量级不同，处理手段也不同。</p><hr><h2 id="系列导航-1" tabindex="-1">系列导航 <a class="header-anchor" href="#系列导航-1" aria-label="Permalink to “系列导航”">​</a></h2>`,63),a(`ul`,null,[l[11]||=a(`li`,null,[a(`strong`,null,`前置：机械臂构型与三只眼睛`),n(` ← 当前`)],-1),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/coordinate-chain.html`},{default:i(()=>[...l[6]||=[n(`（一）坐标映射链与深度采样`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/hand-eye-calibration.html`},{default:i(()=>[...l[7]||=[n(`（二）手眼标定：从 ChArUco 到最小二乘`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/vision-detection.html`},{default:i(()=>[...l[8]||=[n(`（三）目标检测的工程化`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/inspection-orchestration.html`},{default:i(()=>[...l[9]||=[n(`（四）任务编排与安全判据`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/manipulation/udp-control-loop.html`},{default:i(()=>[...l[10]||=[n(`（五）控制回路的时序与协议`,-1)]]),_:1})])])])}var f=s(u,[[`render`,d]]);export{l as __pageData,f as default};